-- Añade a Responsabilidades > Relaciones institucionales > Contactos los clubes de la web
-- (154) sin pisar lo que ya tengas:
--   · Si ya hay un contacto con el mismo nombre de entidad, se respeta tal cual.
--   · Excepción: los contactos creados por este mismo script (id "seed-...") que aún no has tocado
--     (sin nombre, correo, teléfono ni web) se actualizan con los datos verificados nuevos.
-- Es seguro ejecutarlo varias veces.
-- Solo llevan correo/teléfono/web los datos vistos en texto en una página oficial del propio club; el resto
-- queda vacío para completarlo desde el panel (Editar contacto).
-- Ejecutar: npx wrangler d1 execute <BASE_DE_DATOS> --remote --file=contactos_clubes.sql

INSERT INTO settings (key, value, updated_at)
SELECT 'responsabilidades', '{"relaciones":{"clubes":[],"contactos":[]},"rrhh":{"redactores":[],"fotografos":[],"fichajes":[]}}', datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM settings WHERE key = 'responsabilidades');

UPDATE settings
SET value = json_set(
      value,
      '$.relaciones.contactos',
      json((
